from pwn import *

def test_input(host, port, input_data):
    try:
        conn = remote(host, port)
        conn.sendline(input_data)
        response = conn.recvline(timeout=5)
        conn.close()
        return response.decode('utf-8', errors='ignore')
    except Exception as e:
        return str(e)

def main():
    host = "android-dropper.csaw.io"
    port = 3000

    inputs = {
        "newline_separated": "\n".join(map(str, range(1, 31))),
        "comma_separated": ",".join(map(str, range(1, 31))),
        "tab_separated": "\t".join(map(str, range(1, 31))),
        "random_numbers": " ".join(map(str, [41, 23, 56, 17, 98, 33, 72, 10, 54, 67, 21, 88, 4, 36, 70, 93, 19, 46, 8, 71, 64, 25, 13, 58, 6, 92, 9, 35, 38, 90]))
    }

    for form, data in inputs.items():
        print(f"Testing {form} format:")
        response = test_input(host, port, data)
        print(response)
        print("-" * 50)

if __name__ == "__main__":
    main()

